package com.bank.report;

import java.util.*;
import java.util.logging.*;

public class StaffReportDemo {
    private static final Logger log = Logger.getLogger("StaffReport");
    static {
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
    }

    public static void main(String[] args) {
        List<Employee> staff = new ArrayList<>(List.of(
            new Employee(1L, "Rajesh Kumar", "IT", 95000.0),
            new Employee(2L, "Priya Sharma", "Finance", 250000.0),
            new Employee(3L, "Amit Verma", "IT", 120000.0),
            new Employee(4L, "Sneha Rao", "Finance", 180000.0),
            new Employee(5L, "Vikram Singh", "IT", 95000.0)
        ));
        StaffReportService service = new StaffReportService();
        List<Employee> sorted = service.sortByDeptThenSalaryDesc(staff);
        log.info("Compensation register (dept A-Z, salary high-low):");
        sorted.forEach(e -> log.info(() ->
            String.format("  %-10s | %-14s | %.2f", e.getDepartment(), e.getName(), e.getSalary())));
    }
}

// ─── Would be in model/Employee.java ───
class Employee {
    private final Long id;
    private final String name;
    private final String department;
    private final double salary;
    Employee(Long id, String name, String department, double salary) {
        this.id = id; this.name = name; this.department = department; this.salary = salary;
    }
    Long getId() { return id; }
    String getName() { return name; }
    String getDepartment() { return department; }
    double getSalary() { return salary; }
}

// ─── Would be in service/StaffReportService.java ───
class StaffReportService {
    // Primary: department A-Z. Secondary (tie-breaker): salary HIGH to LOW.
    List<Employee> sortByDeptThenSalaryDesc(List<Employee> employees) {
        return employees.stream()
            .sorted(Comparator.comparing(Employee::getDepartment)
                .thenComparing(Employee::getSalary, Comparator.reverseOrder()))
            .toList();
    }
}
